import { useCart } from "./CartContext";
import "./cart.css";
import Ao1 from "../images/ao1.jpg";
import Ao2 from "../images/ao2.jpg";
import Ao3 from "../images/ao3.jpg";

const recommendedProducts = [
    { id: 4, name: "Áo Polo Nam", price: 999, image: Ao1 },
    { id: 5, name: "Áo Polo Nam", price: 899, image: Ao2 },
    { id: 6, name: "Áo Polo Nam", price: 799, image: Ao3 }
];

const Cart = () => {
    const { cart, removeFromCart, totalItems, totalPrice, checkout, addToCart } = useCart();

    return (
        <div className="cart-container">
            <h2>🛒 Giỏ hàng ({totalItems} sản phẩm)</h2>
            {cart.length === 0 ? (
                <p>Giỏ hàng của bạn đang trống.</p>
            ) : (
                <>
                    {cart.map((product) => (
                        <div key={product.id} className="cart-item">
                            <img src={product.image} alt={product.name} className="product-image" />
                            <span>{product.name} - ${product.price}</span>
                            <button className="btnCart" onClick={() => removeFromCart(product.id)}>Xóa</button>
                        </div>
                    ))}
                    <h3>💰 Tổng tiền: ${totalPrice}</h3>
                    <button className="checkout-btn" onClick={checkout}>🛍 Thanh toán</button>
                </>
            )}

            {/* 🎯 Phần gợi ý sản phẩm */}
            <div className="recommended-section">
                <h3>🔥 Sản phẩm gợi ý</h3>
                <div className="recommended-list">
                    {recommendedProducts.map((product) => (
                        <div key={product.id} className="recommended-item">
                            <img src={product.image} alt={product.name} className="recommended-image" />
                            <span>{product.name} - ${product.price}</span>
                            <button className="add-to-cart" onClick={() => addToCart(product)}>Thêm vào giỏ</button>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Cart;
